/** El TASKVALUE de entrada es la operación y el de salida es el resultado para el WFL. */
public enum OperacionP000 {
    AVANZA_FECHA(0), CONSULTA_FECHA(1), SIGUIENTE_SISTEMA(16), SIGUIENTE_SISTEMA_ALT(17);
    final int taskValue;
    OperacionP000(int v) { taskValue = v; }
    static Optional<OperacionP000> de(int v) {
        return Arrays.stream(values()).filter(o -> o.taskValue == v).findFirst();
    }
}

@Configuration
public class ControlFechasJobConfig {

    @Bean
    Job controlFechas(JobRepository repo, Step resuelveControl, Step fechas, Step proxSistema) {
        JobExecutionDecider porOperacion = (job, step) -> new FlowExecutionStatus(
                OperacionP000.de(job.getJobParameters().getLong("taskValue", 0L).intValue())
                        .map(o -> o == OperacionP000.SIGUIENTE_SISTEMA
                                  || o == OperacionP000.SIGUIENTE_SISTEMA_ALT ? "SISTEMA" : "FECHAS")
                        .orElse("NADA"));                          // ELSE: vacío en el CASE
        return new JobBuilder("S151P000", repo)
                .start(resuelveControl)                            // VERSIONES
                .next(porOperacion).on("FECHAS").to(fechas)
                .from(porOperacion).on("SISTEMA").to(proxSistema)
                .from(porOperacion).on("NADA").end()
                .end().build();
    }
}

@Component
@RequiredArgsConstructor
class ControlS151Resolver implements Tasklet {

    private final SoporteComsClient soporte;   // CSIID
    private final CtlVersClient ctlvers;       // DAME_TIT
    private final P000Properties props;

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        // El original reintenta LINKLIBRARY sin espera ni límite; aquí hay tope y backoff.
        int csi = RetryTemplate.builder().maxAttempts(props.intentosLiga())
                .exponentialBackoff(500, 2, 10_000).build()
                .execute(r -> soporte.csiId().numCsi());
        String libControl = ctlvers.dameTitulo("S151L001CTL ")
                .orElseGet(() -> {
                    log.warn("ERROR EN CTLVERS, NO EXISTE IDENTIFICADOR DE LIBRERIA CONTROL S151");
                    return props.libControlRespaldo();   // (S151)S151/OBJECT/L001/CONTROL ON CMEMP.
                });
        var ec = ctx.getStepContext().getStepExecution().getJobExecution().getExecutionContext();
        ec.putInt("csi", csi);
        ec.putString("libControl", libControl);
        return RepeatStatus.FINISHED;
    }
}

@Component
@RequiredArgsConstructor
class FechaOperativa {

    private final CalendarioBancario calendario;   // THECALENDAR IN LOCSUP
    private final Clock reloj;
    @Value("${p000.hora-corte:12:00}") private LocalTime horaCorte;

    /** Antes del mediodía la corrida pertenece al día anterior (función 10, formato 13, un día). */
    LocalDate hoy() {
        LocalDateTime ahora = LocalDateTime.now(reloj);
        LocalDate fecha = ahora.toLocalDate();
        return ahora.toLocalTime().isBefore(horaCorte) ? calendario.restaDias(fecha, 1) : fecha;
    }
}

@Component
@RequiredArgsConstructor
public class FechasTasklet implements Tasklet {

    private final ControlAdSaldoService control;   // S151BD02ADSALDO, registro B92
    private final FechaOperativa fechaOperativa;

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var job = ctx.getStepContext().getStepExecution().getJobExecution();
        LocalDate fechaBase = control.fechaControl()
                .orElseThrow(() -> new ProcesoAbortadoException("ERROR EN FIND S151BD02ADSALDO"));

        if (job.getJobParameters().getLong("taskValue", 0L) == 1) {
            // MYSELF.VALUE := fecha base: el WFL recibe AAAAMMDD como resultado
            job.getExecutionContext().putString("resultado", fechaBase.format(BASIC_ISO_DATE));
            c.setExitStatus(new ExitStatus("FECHA", fechaBase.format(BASIC_ISO_DATE)));
            return RepeatStatus.FINISHED;
        }
        avanzaSiCorresponde(job, fechaBase, fechaOperativa.hoy());
        return RepeatStatus.FINISHED;
    }
}

private void avanzaSiCorresponde(JobExecution job, LocalDate fechaBase, LocalDate hoy) {
    Optional<LocalDate> forzada = ParametroP000.fecha(job.getJobParameters());   // PARAMETRO[0] 8 dígitos
    boolean hayParametro = ParametroP000.valor(job.getJobParameters()) > 0;

    if (!hoy.isBefore(fechaBase) || hayParametro) {
        LocalDate nueva = calendario.sumaDias(fechaBase, 1);               // función 13: día siguiente
        if (forzada.filter(f -> f.isAfter(LocalDate.of(1991, 4, 1))).isPresent()) {
            nueva = forzada.get();                                       // > 19910401
        }
        log.info("FECHA MANANA {}", nueva);
        if (control.actualizaFecha(nueva) != 0) {                        // GLOBAL función 61
            throw new ProcesoAbortadoException("BASE DE DATOS NO DISPONIBLE.");
        }
    } else {
        log.info("PRELINEA HASTA {}.", fechaBase);                       // la base ya va adelantada
    }
}

@Service
@RequiredArgsConstructor
public class ControlAdSaldoService {

    private final ControlAdSaldoRepository b92;    // registro único de S151BD02ADSALDO

    /** GLOBAL función 61 / ACTGLOB: 0 correcto, 1 registro no encontrado, 9 error de base. */
    @Transactional
    public int actualizaFecha(LocalDate nueva) {
        var ctl = b92.findForUpdate().orElse(null);          // LOCK S151BD02ADSALDO
        if (ctl == null) return 1;
        ctl.setFecha(nueva);                                 // B92-CTR-FECHA
        for (int i = 1; i <= 20; i++) {
            ctl.setArribo(i, 0);                             // B92-CTR-ARRIBO[1..20]
        }
        return 0;   // STORE dentro de BEGINTRANSACTION / ENDTRANSACTION al confirmar
    }
}

/** a2k_conv_amd_to_camd_int: AAMMDD a CCAAMMDD con año base 50 (Cronos 2000). */
public final class PivoteY2k {
    private static final int ANIO_BASE = 50;              // a2k_base_year

    public static LocalDate deAammdd(int aammdd) {
        int aa = aammdd / 10_000;
        int siglo = (aa >= ANIO_BASE) ? 1900 : 2000;      // 50..99 -> 19xx, 00..49 -> 20xx
        return LocalDate.of(siglo + aa, (aammdd / 100) % 100, aammdd % 100);
    }

    // Equivalente con java.time: el pivote queda explícito en el formateador.
    static final DateTimeFormatter AAMMDD = new DateTimeFormatterBuilder()
            .appendValueReduced(ChronoField.YEAR, 2, 2, 1950)
            .appendPattern("MMdd").toFormatter();
}

@Component
@RequiredArgsConstructor
public class SiguienteSistemaTasklet implements Tasklet {

    private final ControlS151Client control;   // CONSISDIA, CONSISMEN, B04SISTEM, B05PROCESOS
    public static final int SIN_SISTEMA = 9999;

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var job = ctx.getStepContext().getStepExecution().getJobExecution();
        int csi = job.getExecutionContext().getInt("csi");
        int sistema = job.getJobParameters().getLong("pa").intValue();

        // Alta disponibilidad 2015: fuera de S500, con TASKVALUE 16 se reanuda desde B05PROCESOS.
        if (sistema != 500 && job.getJobParameters().getLong("taskValue") == 16) {
            sistema = control.ultimoSistemaProcesado(151, csi).orElse(sistema);
        }

        int resultado = SIN_SISTEMA;
        for (var s : control.sistemasDespuesDe(sistema)) {        // B04SISTEM función 02
            if (s.estatus() != 3) continue;                        // solo sistemas activos
            if (control.consultaSistemaDia(s.numero(), csi).isEmpty()) continue;     // CONSISDIA
            var men = control.consultaSistemaMensual(s.numero());                    // CONSISMEN
            if (men.isPresent() && (men.get().csiResidente() == csi || men.get().csiResidente() == 0)) {
                resultado = s.numero();                            // MYSELF.VALUE := SISTEMA
                break;
            }
        }
        c.setExitStatus(new ExitStatus(String.valueOf(resultado)));
        return RepeatStatus.FINISHED;
    }
}
